/**
 * Event names from the FMS. A robot log's `EventName` is usually The Blue Alliance's event code ("cacg", "CASNF") or, at
 * Championship, a division's name ("MILSTEIN"); a person reading the library wants the name. The names come from a
 * committed table per year (`events/<year>.json`, generated by `scripts/build-event-table.ts` from TBA's public event list),
 * so the app needs no key and works offline. A code the table lacks resolves to nothing, and the day keeps its typed place.
 * No `node:` imports: the Library view uses this.
 */

const files = import.meta.glob('./events/*.json', { eager: true, import: 'default' }) as Record<string, Record<string, string>>

/** Year -> (lowercase event code without the year -> name). Keys starting with "_" are notes, never events. */
const TABLES: Map<number, Map<string, string>> = new Map(
  Object.entries(files).flatMap(([path, table]) => {
    const year = Number(/(\d{4})\.json$/.exec(path)?.[1])
    return Number.isFinite(year) ? [[year, new Map(Object.entries(table).filter(([k, v]) => !k.startsWith('_') && typeof v === 'string'))] as const] : []
  }),
)

export function eventTableYears(): number[] { return [...TABLES.keys()].sort() }

/**
 * The name of the event a log's FMS `event` string means in the year it was played (ms since 1970, UTC year), or null when
 * the string is empty or the table does not know it. Case-insensitive. A string that is not a code but a division word
 * ("MILSTEIN") matches the entry named "<Word> Division".
 */
export function resolveEvent(event: string, playedAt: number | null): string | null {
  const key = event.trim().toLowerCase()
  if (key === '' || playedAt === null) return null
  const table = TABLES.get(new Date(playedAt).getUTCFullYear())
  if (!table) return null
  const byCode = table.get(key)
  if (byCode) return byCode
  const division = `${key} division`
  for (const name of table.values()) if (name.toLowerCase() === division) return name
  return null
}
